const fs = require("fs");
const cp = require("child_process");
let out = "";
try {
  out = cp.execSync("node scripts/check-spec-anchor-names.mjs", {encoding: "utf8"});
} catch (e) {
  out = e.stderr || e.stdout || e.message;
}

const files = {};
for (const line of out.split("\\n")) {
  const match = line.trim().match(/^check-spec-anchor-names: (.*?): names ".*?" but points at #(L\\d+); it is at #(L\\d+)/);
  if (match) {
    const file = match[1];
    if (!files[file]) files[file] = fs.readFileSync(file, "utf8");
    files[file] = files[file].replace("#" + match[2] + ")", "#" + match[3] + ")");
  }
}
for (const [file, content] of Object.entries(files)) {
  fs.writeFileSync(file, content);
}
