cd target && python3 -c '
import subprocess
import re

try:
    subprocess.check_output(["node", "scripts/check-spec-anchor-names.mjs"], stderr=subprocess.STDOUT)
    out = ""
except subprocess.CalledProcessError as e:
    out = e.output.decode("utf-8")

files = {}
for line in out.split("\n"):
    match = re.match(r"^check-spec-anchor-names: (.*?): names \".*?\" but points at #(L\d+); it is at #(L\d+)", line.strip())
    if match:
        file = match.group(1)
        old_anchor = match.group(2)
        new_anchor = match.group(3)
        if file not in files:
            with open(file, "r") as f:
                files[file] = f.read()
        files[file] = files[file].replace("#" + old_anchor + ")", "#" + new_anchor + ")")

for file, content in files.items():
    with open(file, "w") as f:
        f.write(content)
' && node scripts/check-spec-anchor-names.mjs
